package net.battlespades.bot;
import java.util.*;
import static net.battlespades.bot.BotMessages.*;
import static net.battlespades.bot.BotVectors.*;

/** Fair visual acquisition: public markers rank only candidates already admitted by FOV, range and live LOS. */
final class BrainTargeting {
    private BrainTargeting(){}
    static Player visible(BotNavigationWorld world,Perception f,Player p,BotBrainState state,BotModeDecision decision){if(!p.canShoot())return null;var candidates=new ArrayList<Player>();for(var q:f.players()){if(q.team()==p.team()||!q.alive()||!q.spawned()||q.spawnProtected())continue;double distance=distance(p.eye(),q.eye());if(distance>160||!BotModePolicies.allowsCombat(decision,p,q,f.createdAt()))continue;double dx=q.eye().x()-p.eye().x(),dy=q.eye().y()-p.eye().y(),horizontal=Math.hypot(dx,dy);if(horizontal>1e-6&&distance>20){double facing=(p.orientation().x()*dx+p.orientation().y()*dy)/horizontal;boolean hit=p.lastDamageSourceId()==q.id()&&p.lastDamageAt()>0&&f.createdAt()-p.lastDamageAt()<=2,tracking=state.contactId==q.id()&&state.contactGeneration==q.generation();if(facing<-.2&&!hit&&!tracking)continue;}if(world.lineOfSight(p.eye(),q.eye()))candidates.add(q);}if(candidates.isEmpty())return null;var current=candidates.stream().filter(q->q.id()==state.contactId&&q.generation()==state.contactGeneration).findFirst().orElse(null);String mode=BotModePolicies.canonical(f.mode());var markedIds=new HashSet<Integer>();for(var o:f.objectives())if(o.carrierId()>=0&&(mode.equals("vip")&&o.kind().equals("vip")&&o.team()!=p.team()||Set.of("ctf","cctf").contains(mode)&&o.kind().equals("ctf_intel")&&o.team()==p.team()))markedIds.add(o.carrierId());var marked=candidates.stream().filter(q->markedIds.contains(q.id())).min(Comparator.comparingDouble(q->distance(p.position(),q.position()))).orElse(null);var urgent=candidates.stream().filter(q->distance(p.position(),q.position())<=4.5||p.lastDamageSourceId()==q.id()&&BotModePolicies.hurt(f,p,1)).toList();var threat=current!=null&&urgent.contains(current)?current:urgent.stream().min(Comparator.comparingDouble(q->distance(p.position(),q.position()))).orElse(null);var target=threat!=null?threat:marked!=null?marked:current!=null?current:candidates.stream().min(Comparator.comparingDouble((Player q)->distance(p.position(),q.position())).thenComparingInt(Player::id)).orElseThrow();boolean changed=state.contactId!=target.id()||state.contactGeneration!=target.generation();state.contactId=target.id();state.contactGeneration=target.generation();state.contactPosition=target.position();state.contactUntil=f.createdAt()+4;if(changed)state.acquiredAt=f.createdAt();return target;}
}
